from pathlib import Path
import hashlib,json,resource,subprocess,time
BASE=Path('/tmp/oec/pequalnp-pilot-78');OUT=BASE/'numeric/incidence-module-slimgb';OUT.mkdir(exist_ok=True)
source=BASE/'geometry_search/tracezero_rankdrop/shifted-matrix.json';assert hashlib.sha256(source.read_bytes()).hexdigest()=='5a591213eff5d830ecaef80497310d9be0122e9060aa39909382276929e8bcf6'
data=json.loads(source.read_text());variables=data['variables'];rows=data['matrix'];flats=data['flat_generators'];assert len(variables)==12 and len(rows)==9 and all(len(row)==7 for row in rows) and len(flats)==12
def polynomial(text):return str(text).replace('**','^')
lines=['LIB "modstd.lib";','ring R=0,('+','.join(variables)+'),(dp,c);','option(prot);','matrix A[7][93];']
for i,row in enumerate(rows):
    for j,value in enumerate(row):
        if str(value)!='0':lines.append(f'A[{j+1},{i+1}]={polynomial(value)};')
for i,f in enumerate(flats):
    for j in range(7):lines.append(f'A[{j+1},{10+7*i+j}]={polynomial(f)};')
lines+=['module M=module(A);','module E=[0,0,0,0,0,0,1];','print("BEGIN_MODULAR_MODULE_BASIS");','module G=modGB("slimgb",M,1);','print("END_MODULAR_MODULE_BASIS");','print("BASIS_SIZE");size(G);','module N=reduce(E,G);','print("TARGET_REMAINDER_SIZE");size(N);','if(size(N)==0){','print("CANDIDATE_MEMBERSHIP_EXACT_LIFT_START");','matrix C=lift(M,E);','matrix residual=matrix(M)*C-matrix(E);','print("EXACT_LIFT_RESIDUAL");residual;','print("EXACT_LIFT_CERTIFICATE");C;','print("EXACT_LIFT_END");','}','quit;']
(OUT/'probe.sing').write_text('\n'.join(lines)+'\n')
def limits():
    resource.setrlimit(resource.RLIMIT_CPU,(300,305));resource.setrlimit(resource.RLIMIT_AS,(512*2**20,512*2**20));resource.setrlimit(resource.RLIMIT_CORE,(0,0));resource.setrlimit(resource.RLIMIT_FSIZE,(8*2**20,8*2**20))
start=time.monotonic()
with(OUT/'probe.stdout').open('w')as out,(OUT/'probe.stderr').open('w')as err:
    try:r=subprocess.run([str(BASE/'numeric/singular/bin/Singular'),'--quiet','--no-tty','--no-rc','--no-shell','--cpus=1','--threads=1','--flint-threads=1',str(OUT/'probe.sing')],stdin=subprocess.DEVNULL,stdout=out,stderr=err,preexec_fn=limits,timeout=900);code=r.returncode
    except subprocess.TimeoutExpired:code='timeout'
report={'exit':code,'wall_seconds':time.monotonic()-start,'memory_mib':512,'cpu_budget_seconds':300,'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'generators':93,'components':7,'ring_variables':12,'scope':'Module generated by nine linear-incidence rows and twelve flat equations times each coordinate; target constant-coordinate basis vector. Only an independently verified exact lift proves inconsistency; all unfinished or nonmembership outcomes inconclusive.'};(OUT/'result.json').write_text(json.dumps(report,indent=2));print(json.dumps(report),flush=True)
